# Generated by build.py from recipe.yml for recipe ldaps-search-over-tls. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--user', 'alice:s3cret', 'ldaps://127.0.0.1:8080/', 'ldap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -k -u alice:s3cret "ldaps://127.0.0.1:8080/dc=example,dc=com?mail?sub?(cn=bob)" } finally { Stop-Process $server0 }
